const root=document.documentElement;let savedTheme=null;try{savedTheme=localStorage.getItem("theme")}catch{}const systemPrefersDark=window.matchMedia("(prefers-color-scheme: dark)").matches;root.setAttribute("data-theme",savedTheme||(systemPrefersDark?"dark":"light")),document.addEventListener("DOMContentLoaded",()=>{document.getElementById("theme-toggle").addEventListener("click",()=>{const e=root.getAttribute("data-theme")==="dark"?"light":"dark";root.setAttribute("data-theme",e);try{localStorage.setItem("theme",e)}catch{}})})